import numpy as np

# Deteksi Bahasa di Tingkat Token (Token-Level Language Identification) untuk Code-Switching
def token_level_lid(tokens, lexicon_id, lexicon_en):
    tagged = []
    for tok in tokens:
        t_low = tok.lower()
        if t_low in lexicon_id and t_low in lexicon_en:
            tag = 'AMBIGUOUS'
        elif t_low in lexicon_id:
            tag = 'LANG_ID'
        elif t_low in lexicon_en:
            tag = 'LANG_EN'
        elif any(c.isdigit() for c in tok) or tok in [',', '.', '!', '?']:
            tag = 'OTHER'
        else:
            tag = 'SLANG/UNKNOWN'
        tagged.append((tok, tag))
    return tagged

lex_id = {'gue', 'udah', 'hal', 'itu', 'di', 'dan', 'sama', 'kemarin'}
lex_en = {'literally', 'expect', 'jujurly', 'meeting', 'client', 'which', 'is'}

sentence = "Literally gue udah expect hal itu jujurly pas meeting kemarin"
tokens = sentence.split()
lid_results = token_level_lid(tokens, lex_id, lex_en)

print(f"Kalimat Code-Switching: '{sentence}'\n")
print("Hasil Pelabelan Token-Level Language ID:")
for tok, tag in lid_results:
    print(f"  {tok:<12} : [{tag}]")
